-- `(uuid, text)` with 2 677 characters is refused: the uuid takes 16 unaligned bytes.
-- @setup
CREATE TABLE t (u uuid, a text);
CREATE INDEX t_i ON t (u, a);
-- @test
-- @expect-error: a uuid and a text part over the limit
-- @expect-message
-- @profile-lock
INSERT INTO t VALUES ('00000000-0000-4000-8000-000000000001', '');
